1	//! Configuration loading, parsing, and validation for Bivvy.
2	//!
3	//! This module handles all aspects of configuration:
4	//! - Schema definitions in [`schema`]
5	//! - File discovery and loading in [`loader`]
6	//! - Deep merging in [`merger`]
7	//! - Validation in [`validator`]
8	//! - Variable interpolation in [`interpolation`]
9	//! - Environment variable handling in [`environment`]
10	//!
11	//! # Example
12	//!
13	//! ```
14	//! use bivvy::config::{load_merged_config, validate};
15	//! use tempfile::TempDir;
16	//! use std::fs;
17	//!
18	//! let temp = TempDir::new().unwrap();
19	//! let bivvy_dir = temp.path().join(".bivvy");
20	//! fs::create_dir_all(&bivvy_dir).unwrap();
21	//! fs::write(bivvy_dir.join("config.yml"), "app_name: test").unwrap();
22	//!
23	//! let config = load_merged_config(temp.path()).unwrap();
24	//! validate(&config).unwrap();
25	//! assert_eq!(config.app_name, Some("test".to_string()));
26	//! ```
27	//!
28	//! # Configuration File Locations
29	//!
30	//! Bivvy discovers and merges configuration in this order:
31	//! 1. Remote base configs (from `extends:`)
32	//! 2. User global config (`~/.bivvy/config.yml`)
33	//! 3. Project config (`.bivvy/config.yml`)
34	//! 4. Split-file steps (`.bivvy/steps/*.yml`)
35	//! 5. Split-file workflows (`.bivvy/workflows/*.yml`)
36	//! 6. Local overrides (`.bivvy/config.local.yml`)
37	
38	pub mod discovery;
39	pub mod env_file;
40	pub mod env_layer;
41	pub mod environment;
42	pub mod extends;
43	pub mod interpolation;
44	pub mod loader;
45	pub mod merger;
46	pub mod remote;
47	pub mod schema;
48	pub mod trust;
49	pub mod validator;
50	pub mod vars;
51	
52	// Schema re-exports
53	pub use schema::{
54	    BehaviorConfig, BivvyConfig, CustomRequirement, CustomRequirementCheck, EnvVarSettings,
55	    EnvironmentProfileSettings, EnvironmentScopingConfig, EnvironmentVarsConfig, ExecutionConfig,
56	    ExecutionSettings, HookConfig, OutputMode, PromptConfig, PromptType, SecretConfig, Settings,
57	    StepConfig, StepEnvironmentOverride, StepOutputConfig, StepOutputSettings, StepOverride,
58	    TemplateSource, VarDefinition, WorkflowConfig, WorkflowFile, WorkflowSettings,
59	};
60	
61	// Discovery re-exports
62	pub use discovery::{Discovery, WorkflowHeader};
63	
64	// Check type re-exports (new check system)
65	pub use crate::checks::{
66	    BaselineConfig, ChangeKind, Check, CheckOutcome, CheckResult as NewCheckResult, OnChange,
67	    PresenceKind, SatisfactionCondition, SizeLimit, SnapshotScope, ValidationMode,
68	};
69	
70	// Vars re-exports
71	pub use vars::evaluate_vars;
72	
73	// Loader re-exports
74	pub use loader::{
75	    ensure_global_config, find_project_root, load_config, load_config_file, load_config_value,
76	    load_for_run, load_for_run_with_resolver, load_for_run_with_trust, load_merged_config,
77	    load_merged_config_with_resolver, load_merged_config_with_trust, load_project_config,
78	    load_single_step_file, load_single_workflow_file, parse_config, parse_workflow_file_value,
79	    ConfigPaths,
80	};
81	
82	// Merger re-exports
83	pub use merger::{deep_merge, merge_configs};
84	
85	// Validator re-exports
86	pub use validator::{validate, validate_config, ValidationError};
87	
88	// Interpolation re-exports
89	pub use interpolation::{
90	    extract_variables, has_interpolation, parse_interpolation, resolve_string,
91	    resolve_string_with_default, InterpolationContext, Segment,
92	};
93	
94	// Environment re-exports
95	pub use environment::{
96	    is_secret, load_env_file, load_env_file_optional, load_system_env, merge_env, SECRET_PATTERNS,
97	};
98	
99	// Remote re-exports
