1	//! Templates command implementation.
2	//!
3	//! The `bivvy templates` command lists all available templates from
4	//! all sources (built-in, local, remote), organized by category.
5	
6	use std::path::{Path, PathBuf};
7	
8	use crate::cli::args::TemplatesArgs;
9	use crate::config::load_merged_config;
10	use crate::error::{BivvyError, Result};
11	use crate::registry::resolver::Registry;
12	use crate::ui::theme::BivvyTheme;
13	use crate::ui::UserInterface;
14	
15	use super::dispatcher::{Command, CommandResult};
16	
17	/// The templates command implementation.
18	pub struct TemplatesCommand {
19	    project_root: PathBuf,
20	    args: TemplatesArgs,
21	}
22	
23	impl TemplatesCommand {
24	    /// Create a new templates command.
25	    pub fn new(project_root: &Path, args: TemplatesArgs) -> Self {
26	        Self {
27	            project_root: project_root.to_path_buf(),
28	            args,
29	        }
30	    }
31	
32	    /// Get the project root path.
33	    pub fn project_root(&self) -> &Path {
34	        &self.project_root
35	    }
36	
37	    /// Get the command arguments.
38	    pub fn args(&self) -> &TemplatesArgs {
39	        &self.args
40	    }
41	}
42	
43	impl Command for TemplatesCommand {
44	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
45	        // If the project has a config with template_sources, surface those
46	        // remote templates too. When there's no config (e.g. a brand-new
47	        // project), fall back to the local + built-in registry.
48	        let registry = match load_merged_config(&self.project_root) {
49	            Ok(config) if !config.template_sources.is_empty() => {
50	                Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
51	            }
52	            Ok(_) | Err(BivvyError::ConfigNotFound { .. }) => {
53	                Registry::new(Some(&self.project_root))?
54	            }
55	            Err(e) => return Err(e),
56	        };
57	        let manifest = registry.builtin().manifest();
58	        let theme = BivvyTheme::new();
59	
60	        ui.show_header("Available Templates");
61	        ui.message("");
62	
63	        let mut shown_count = 0;
64	
65	        for category in &manifest.categories {
66	            // Filter by category if specified
67	            if let Some(ref filter) = self.args.category {
68	                if category.name != *filter {
69	                    continue;
70	                }
71	            }
72	
73	            // Collect templates in this category that actually exist
74	            let mut category_templates: Vec<_> = category
75	                .templates
76	                .iter()
77	                .filter_map(|name| registry.get(name).map(|t| (name.as_str(), t)))
78	                .collect();
79	
80	            if category_templates.is_empty() {
81	                continue;
82	            }
83	
84	            // Filter by platform
85	            category_templates.retain(|(_, t)| t.platforms.iter().any(|p| p.is_current()));
86	
87	            if category_templates.is_empty() {
88	                continue;
89	            }
90	
91	            // Category header
92	            ui.message(&format!(
93	                "  {} {}",
94	                theme.key.apply_to(&category.name),
95	                theme.dim.apply_to(format!("— {}", category.description)),
96	            ));
97	
98	            for (name, template) in &category_templates {
99	                ui.message(&format!(
100	                    "    {}  {}",
101	                    theme.highlight.apply_to(name),
102	                    theme.dim.apply_to(&template.description),
103	                ));
104	                shown_count += 1;
105	            }
106	
107	            ui.message("");
108	        }
109	
110	        // Show local/remote templates that aren't in the manifest.
111	        // Registry keys are qualified (category/name), manifest uses unqualified names,
112	        // so extract the unqualified name for comparison.
113	        let all_names = registry.all_template_names();
114	        let manifest_names: Vec<&str> = manifest.all_template_names().into_iter().collect();
115	        let extra: Vec<_> = all_names
116	            .iter()
117	            .filter(|n| {
118	                let unqualified = n.rsplit_once('/').map_or(n.as_str(), |(_, name)| name);
119	                !manifest_names.contains(&unqualified)
120	            })
121	            .collect();
122	
123	        if !extra.is_empty() && self.args.category.is_none() {
124	            ui.message(&format!(
125	                "  {} {}",
126	                theme.key.apply_to("custom"),
127	                theme.dim.apply_to("— Project and user templates"),
128	            ));
129	            for name in &extra {
130	                if let Some(template) = registry.get(name) {
131	                    ui.message(&format!(
132	                        "    {}  {}",
133	                        theme.highlight.apply_to(name.as_str()),
134	                        theme.dim.apply_to(&template.description),
135	                    ));
136	                    shown_count += 1;
137	                }
138	            }
139	            ui.message("");
140	        }
141	
142	        ui.message(&format!(
143	            "  {} templates available. Use `bivvy add <template>` to add one.",
144	            shown_count
145	        ));
146	
147	        Ok(CommandResult::success())
148	    }
149	}
