        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.settings._unknown.is_empty());
        assert!(config.steps["test"]._unknown.is_empty());
    }

    #[test]
    fn check_unknown_fields_returns_error_for_settings_typo() {
        let yaml = r#"
settings:
  paralell: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let result = config.check_unknown_fields();
        assert!(result.is_err());
        let fields = result.unwrap_err();
        assert!(fields.iter().any(|f| f.contains("paralell")));
    }

    #[test]
    fn check_unknown_fields_returns_error_for_step_typo() {
        let yaml = r#"
steps:
  test:
    comand: "echo test"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let result = config.check_unknown_fields();
        assert!(result.is_err());
        let fields = result.unwrap_err();
        assert!(fields.iter().any(|f| f.contains("comand")));
        assert!(fields.iter().any(|f| f.contains("test")));
    }

    #[test]
    fn check_unknown_fields_passes_for_valid_config() {
        let yaml = r#"
app_name: Test
settings:
  parallel: true
steps:
  hello:
    command: "echo hello"
workflows:
  default:
    steps: [hello]
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.check_unknown_fields().is_ok());
    }
}

