impl BivvyConfig {
    /// Check for unknown fields that were silently ignored during deserialization.
    ///
    /// `Settings` and `StepConfig` use `#[serde(flatten)]`, which prevents
    /// serde from rejecting unknown fields at parse time. Instead, unknown
    /// fields are captured into `_unknown` catch-all maps. This method
    /// inspects those maps and returns an error listing every unrecognized
    /// field path so the user can fix typos in their config.
    pub fn check_unknown_fields(&self) -> std::result::Result<(), Vec<String>> {
        let mut unknown = Vec::new();

        for key in self.settings._unknown.keys() {
            unknown.push(format!("settings.{}", key));
        }

        for (step_name, step) in &self.steps {
            for key in step._unknown.keys() {
                unknown.push(format!("steps.{}.{}", step_name, key));
            }
        }

        if unknown.is_empty() {
            Ok(())
        } else {
            unknown.sort();
            Err(unknown)
        }
    }

