        assert!(
            err.contains("comand"),
            "Error should mention the unknown field: {}",
            err
        );
    }

    #[test]
    fn load_config_file_rejects_unknown_settings_field() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.yml");
        fs::write(
            &config_path,
            r#"
settings:
  paralell: true
"#,
        )
        .unwrap();

        let result = load_config_file(&config_path);
        assert!(result.is_err(), "Should reject unknown settings field");
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("paralell"),
            "Error should mention the unknown field: {}",
            err
        );
    }

    #[test]
    fn load_merged_config_accepts_valid_settings() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: Test
settings:
  parallel: true
  max_parallel: 8
  defaults:
    output: quiet
steps:
  test:
    command: "echo test"
workflows:
  default:
    steps: [test]
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert!(config.settings.execution.parallel);
        assert_eq!(config.settings.execution.max_parallel, 8);
    }
}

